sources.coarse/draw.hlsli:
#ifndef TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED

#include "../constants.hlsli"
#include "../draw_records.hlsli"
#include "../scene_records.hlsli"
#include "tags.hlsli"

struct CoarseDraw {
    uint path_id, glyph_run_id, sdf_offset, sdf_len, shadow_offset, tag, fill_rule, brush_offset, solid_rect;
    int4 pixel_bounds;
    float4 affine_linear;
    float2 translation;
};
CoarseDraw load_draw(ByteAddressBuffer records, uint index) {
    uint base = index * DRAW_RECORD_STRIDE;
    CoarseDraw draw;
    draw.path_id = records.Load(base + DRAW_PATH);
    draw.glyph_run_id = records.Load(base + DRAW_GLYPH_RUN);
    draw.sdf_offset = records.Load(base + DRAW_SDF);
    draw.sdf_len = records.Load(base + DRAW_SDF_LEN);
    draw.shadow_offset = records.Load(base + DRAW_SHADOW);
    draw.brush_offset = records.Load(base + DRAW_BRUSH_OFFSET);
    draw.solid_rect = records.Load(base + DRAW_SOLID_RECT);
    draw.tag = records.Load(base + DRAW_TAG);
    draw.fill_rule = records.Load(base + DRAW_FILL_RULE);
    draw.pixel_bounds = asint(records.Load4(base + DRAW_PIXEL_BOUNDS));
    draw.affine_linear = asfloat(records.Load4(base + DRAW_TRANSFORM));
    draw.translation = asfloat(records.Load2(base + DRAW_TRANSFORM + AFFINE_TRANSLATION));
    return draw;
}
bool draw_has_sdf(CoarseDraw draw) { return draw.sdf_offset != INVALID_INDEX || draw.shadow_offset != INVALID_INDEX; }
uint tile_min(int pixel, uint limit) { return pixel > 0 ? min(uint(pixel) / TILE_SIZE, limit) : 0u; }
uint tile_max(int pixel, uint limit) { return pixel > 0 ? min((uint(pixel) + TILE_SIZE - 1u) / TILE_SIZE, limit) : 0u; }
bool draw_hits_tile(CoarseDraw draw, uint2 tile, uint2 dimensions) {
    uint2 lower = uint2(tile_min(draw.pixel_bounds.x, dimensions.x), tile_min(draw.pixel_bounds.y, dimensions.y));
    uint2 upper = uint2(tile_max(draw.pixel_bounds.z, dimensions.x), tile_max(draw.pixel_bounds.w, dimensions.y));
    return all(tile >= lower) && all(tile < upper);
}
uint draw_backdrop(ByteAddressBuffer paths, CoarseDraw draw, uint2 tile, uint2 dimensions) {
    uint path_bytes; paths.GetDimensions(path_bytes);
    if (draw.path_id == INVALID_INDEX || draw.tag > DRAW_PATH_GLYPH || draw.path_id >= path_bytes / PATH_RECORD_STRIDE || !draw_hits_tile(draw, tile, dimensions)) return INVALID_INDEX;
    uint base = draw.path_id * PATH_RECORD_STRIDE;
    uint4 bbox = paths.Load4(base + PATH_BBOX);
    if (bbox.z <= bbox.x || any(tile < bbox.xy) || any(tile >= bbox.zw)) return INVALID_INDEX;
    return paths.Load(base + PATH_DATA_OFFSET) + (tile.y - bbox.y) * (bbox.z - bbox.x) + tile.x - bbox.x;
}
float2 draw_point(CoarseDraw draw, float2 position) {
    return float2(draw.affine_linear.x * position.x + draw.affine_linear.z * position.y + draw.translation.x,
                  draw.affine_linear.y * position.x + draw.affine_linear.w * position.y + draw.translation.y);
}
bool transformed_rect_hits_tile(CoarseDraw draw, int4 rect, uint2 tile) {
    float2 p0 = draw_point(draw, float2(rect.xy));
    float2 p1 = draw_point(draw, float2(rect.zy));
    float2 p2 = draw_point(draw, float2(rect.xw));
    float2 p3 = draw_point(draw, float2(rect.zw));
    float2 lower = min(min(p0, p1), min(p2, p3));
    float2 upper = max(max(p0, p1), max(p2, p3));
    float2 tile_lower = float2(tile * TILE_SIZE);
    return all(lower < tile_lower + float(TILE_SIZE)) && all(upper > tile_lower);
}

#endif // TILEINK_HLSL_COARSE_DRAW_HLSLI_INCLUDED

sources.coarse/draw_list.hlsli:
#ifndef TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED

#include "../constants.hlsli"
#include "../coarse_records.hlsli"
#include "config.hlsli"
#include "emit_layout.hlsli"
#include "tags.hlsli"

uint draw_index_base(ConstantBuffer<CoarseConfig> settings) { return tile_draw_base(settings, settings.tile_count); }
uint draw_page_next(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint page) {
    if ((page & DRAW_FLAT_FLAG) != 0u) return page + COARSE_WORKGROUP_SIZE;
    return work.Load(draw_index_base(settings) + page * (COARSE_WORKGROUP_SIZE + 1u) * 4u);
}
uint draw_page_index(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint page, uint slot) {
    uint index = (page & DRAW_FLAT_FLAG) != 0u ? (page & DRAW_FLAT_MASK) + slot : page * (COARSE_WORKGROUP_SIZE + 1u) + 1u + slot;
    return work.Load(draw_index_base(settings) + index * 4u);
}
uint draw_page_at(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint tile, uint local_page) {
    uint page = work.Load(tile_draw_base(settings, tile));
    if ((page & DRAW_FLAT_FLAG) != 0u) return page + local_page * COARSE_WORKGROUP_SIZE;
    for (uint index=0u; index < local_page && page != INVALID_INDEX; index++) page = draw_page_next(work, settings, page);
    return page;
}
void store_tile_counts(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint tile, uint2 count) {
    work.Store(tile * COARSE_TILE_RECORD_STRIDE, count.x);
    work.Store(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_GLYPH_COUNT, count.y);
    uint kind_base = emit_base(settings, settings.emit_chunk_capacity);
    work.Store(kind_base + tile * 4u, count.x > 0u ? TILE_KIND_INTERPRETER : TILE_KIND_EMPTY);
}

#endif // TILEINK_HLSL_COARSE_DRAW_LIST_HLSLI_INCLUDED

sources.coarse/emit.hlsl:
#include "../constants.hlsli"
#include "config.hlsli"
#include "active_tiles.hlsli"
#include "draw_list.hlsli"
#include "prefix_scan.hlsli"
#include "emit_draw.hlsli"
#include "emit_stack.hlsli"
#include "tile_classification.hlsli"

ConstantBuffer<CoarseConfig> config : register(b0, space0);
ByteAddressBuffer draw_records : register(t1, space0);
ByteAddressBuffer text_blob : register(t2, space0);
ByteAddressBuffer sdf_blob : register(t3, space0);
ByteAddressBuffer path_records : register(t4, space0);
ByteAddressBuffer backdrops : register(t5, space0);
ByteAddressBuffer segment_ranges : register(t6, space0);
ByteAddressBuffer layer_stack : register(t7, space0);
RWByteAddressBuffer coarse_work : register(u8, space0);
ByteAddressBuffer draw_batch_ids : register(t9, space0);

[numthreads(COARSE_WORKGROUP_SIZE,1,1)]
void coarse_emit(uint3 group : SV_GroupID, uint3 local : SV_GroupThreadID) {
    if (group.x >= config.active_tile_count) return;
    uint tile = coarse_tile_at(coarse_work, config, group.x);
    if (tile >= config.tile_count) return;
    uint2 position = uint2(tile % config.tiles_width, tile / config.tiles_width);
    uint2 particles = coarse_work.Load2(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_PTCL_START);
    uint2 glyphs = coarse_work.Load2(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_GLYPH_START);
    if (particles.x >= particles.y) return;
    uint wrappers = stack_wrapper_count(config, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, position);
    if (wrappers == INVALID_INDEX) return;
    if (local.x == 0u) emit_stack_begins(config, coarse_work, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, particles.x, position);
    particles.x += wrappers;
    uint2 list = coarse_work.Load2(tile_draw_base(config, tile));
    uint page = list.x, remaining = list.y;
    while (page != INVALID_INDEX && remaining != 0u) {
        uint page_count = min(remaining, COARSE_WORKGROUP_SIZE);
        uint draw_index = INVALID_INDEX;
        if (local.x < page_count) draw_index = draw_page_index(coarse_work, config, page, local.x);
        Particle particle = draw_particle(config, draw_records, text_blob, sdf_blob, path_records, backdrops, segment_ranges, draw_batch_ids, draw_index, position);
        uint2 total;
        uint2 offset = exclusive_prefix(uint2(particle.valid ? 1u : 0u, particle.glyph_count), local.x, total);
        if (particle.valid) {
            if (particle.tag == PTCL_GLYPH) {
                particle.segments = uint2(glyphs.x + offset.y, glyphs.x + offset.y + particle.glyph_count);
                if (particle.segments.y <= glyphs.y) store_draw_glyphs(coarse_work, text_blob, config, load_draw(draw_records, draw_index), position, particle.segments.x);
            }
            store_particle_value(coarse_work, config, particles.x + offset.x, particle);
        }
        particles.x += total.x;
        glyphs.x += total.y;
        remaining -= page_count;
        page = draw_page_next(coarse_work, config, page);
    }
    if (local.x == 0u) {
        emit_stack_ends(config, coarse_work, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, particles.x, position);
        store_particle(coarse_work, config, particles.x + wrappers, PTCL_END, 0u, 0u, uint2(0u,0u), 0u);
    }
}

[numthreads(COARSE_WORKGROUP_SIZE,1,1)]
void coarse_emit_bins(uint3 group : SV_GroupID, uint3 local : SV_GroupThreadID) {
    uint bins_per_row = (config.tiles_width + COARSE_BIN_SIDE - 1u) / COARSE_BIN_SIDE;
    uint2 position = uint2(group.x % bins_per_row, group.x / bins_per_row) * COARSE_BIN_SIDE + uint2(local.x % COARSE_BIN_SIDE, local.x / COARSE_BIN_SIDE);
    if (position.x >= config.tiles_width || position.y >= config.tiles_height) return;
    uint tile = position.y * config.tiles_width + position.x;
    if (tile >= config.tile_count) return;
    uint kind_base = emit_base(config, config.emit_chunk_capacity) + tile * 4u;
    uint2 particles = coarse_work.Load2(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_PTCL_START);
    uint2 glyphs = coarse_work.Load2(tile * COARSE_TILE_RECORD_STRIDE + COARSE_TILE_GLYPH_START);
    if (particles.x >= particles.y) { coarse_work.Store(kind_base, TILE_KIND_EMPTY); return; }
    uint wrappers = stack_wrapper_count(config, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, position);
    if (wrappers == INVALID_INDEX) { coarse_work.Store(kind_base, TILE_KIND_INTERPRETER); return; }
    uint flags = wrappers != 0u ? CHUNK_CLASS_OTHER : 0u;
    emit_stack_begins(config, coarse_work, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, particles.x, position);
    particles.x += wrappers;
    uint2 list = coarse_work.Load2(tile_draw_base(config, tile));
    uint page = list.x, remaining = list.y, slot = 0u;
    while (page != INVALID_INDEX && remaining != 0u) {
        uint draw_index = draw_page_index(coarse_work, config, page, slot);
        Particle particle = draw_particle(config, draw_records, text_blob, sdf_blob, path_records, backdrops, segment_ranges, draw_batch_ids, draw_index, position);
        if (particle.valid) {
            CoarseDraw draw = load_draw(draw_records, draw_index);
            flags |= particle_class_flags(sdf_blob, config, draw, particle.tag);
            if (particle.tag == PTCL_GLYPH) {
                particle.segments = uint2(glyphs.x, glyphs.x + particle.glyph_count);
                if (particle.segments.y <= glyphs.y) store_draw_glyphs(coarse_work, text_blob, config, draw, position, particle.segments.x);
                glyphs.x = particle.segments.y;
            }
            if (particles.x < particles.y) store_particle_value(coarse_work, config, particles.x++, particle);
        }
        slot++;
        remaining--;
        if (slot == COARSE_WORKGROUP_SIZE) { page = draw_page_next(coarse_work, config, page); slot = 0u; }
    }
    emit_stack_ends(config, coarse_work, layer_stack, draw_records, path_records, backdrops, segment_ranges, sdf_blob, particles.x, position);
    store_particle(coarse_work, config, particles.x + wrappers, PTCL_END, 0u, 0u, uint2(0u,0u), 0u);
    coarse_work.Store(kind_base, classify_tile_flags(flags));
}

sources.coarse/emit_draw.hlsli:
#ifndef TILEINK_HLSL_COARSE_EMIT_DRAW_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_EMIT_DRAW_HLSLI_INCLUDED

#include "config.hlsli"
#include "draw.hlsli"
#include "text.hlsli"
#include "paint.hlsli"
#include "particle.hlsli"

Particle draw_particle(ConstantBuffer<CoarseConfig> settings, ByteAddressBuffer draws, ByteAddressBuffer text,
    ByteAddressBuffer paint, ByteAddressBuffer paths, ByteAddressBuffer backdrops, ByteAddressBuffer ranges,
    ByteAddressBuffer batches, uint draw_index, uint2 tile) {
    Particle result = empty_particle();
    uint batch_bytes; batches.GetDimensions(batch_bytes);
    if (draw_index >= batch_bytes / 4u || batches.Load(draw_index * 4u) != settings.draw_start) return result;
    CoarseDraw draw = load_draw(draws, draw_index);
    if (settings.text_enabled != 0u && draw.glyph_run_id != INVALID_INDEX) {
        if (draw.tag == DRAW_BRUSH) {
            result.glyph_count = count_draw_glyphs(text, settings, draw, tile);
            result.valid = result.glyph_count > 0u;
            result.tag = PTCL_GLYPH;
            result.color = draw_index;
        }
        return result;
    }
    if (draw_has_sdf(draw)) {
        if (draw.tag == DRAW_BRUSH) {
            result.valid = true;
            uint color = full_tile_solid(paint, settings, draw, tile);
            if (color != 0u) { result.tag = PTCL_COLOR; result.color = color; }
            else if (full_tile_image(paint, settings, draw, tile)) { result.tag = PTCL_IMAGE; result.color = draw_index; }
            else { result.tag = PTCL_SDF; result.segments.x = draw_index; result.color = draw_index; }
        }
        return result;
    }
    uint backdrop = draw_backdrop(paths, draw, tile, uint2(settings.tiles_width, settings.tiles_height));
    if (backdrop == INVALID_INDEX || (draw.tag != DRAW_BRUSH && draw.tag != DRAW_PATH_GLYPH && draw.tag != DRAW_CLIP)) return result;
    uint2 range = ranges.Load2(backdrop * TILE_SEGMENT_RANGE_STRIDE);
    uint winding = backdrops.Load(backdrop * 4u);
    if (range.x == range.y && winding == 0u) return result;
    result.valid = true;
    result.winding = winding;
    result.fill_rule = draw.fill_rule;
    result.segments = range;
    if (draw.tag == DRAW_CLIP) result.tag = PTCL_BEGIN_CLIP;
    else if (draw.tag == DRAW_PATH_GLYPH) result.tag = PTCL_PATH_GLYPH;
    else if (draw.solid_rect != 0u && draw.affine_linear.y == 0.0 && draw.affine_linear.z == 0.0
        && nontransparent_solid(paint, settings, draw) && range.x == range.y) result.tag = PTCL_COLOR;
    if (result.tag == PTCL_COLOR) result.color = solid_color(paint, settings, draw);
    else if (draw.tag == DRAW_BRUSH || draw.tag == DRAW_PATH_GLYPH) result.color = draw_index;
    return result;
}

#endif // TILEINK_HLSL_COARSE_EMIT_DRAW_HLSLI_INCLUDED

