#ifndef TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED

#include "config.hlsli"
#include "../coarse_records.hlsli"
// Byte offsets through the packed coarse work buffer; preceding regions remain intact.
uint tile_draw_base(ConstantBuffer<CoarseConfig> layout, uint tile) {
    return layout.tile_count * COARSE_TILE_RECORD_STRIDE + layout.ptcl_capacity * COARSE_PTCL_RECORD_STRIDE +
        layout.glyph_capacity * 4u + tile * COARSE_TILE_DRAW_RECORD_STRIDE;
}
uint tile_emit_base(ConstantBuffer<CoarseConfig> layout, uint tile) {
    return tile_draw_base(layout, layout.tile_count) + layout.tile_draw_index_count * 4u + tile * COARSE_TILE_EMIT_RECORD_STRIDE;
}
uint emit_base(ConstantBuffer<CoarseConfig> layout, uint reference) {
    return tile_emit_base(layout, layout.tile_count) + reference * COARSE_EMIT_RECORD_STRIDE;
}

#endif // TILEINK_HLSL_COARSE_EMIT_LAYOUT_HLSLI_INCLUDED

sources.coarse/emit_stack.hlsli:
#ifndef TILEINK_HLSL_COARSE_EMIT_STACK_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_EMIT_STACK_HLSLI_INCLUDED

#include "classify.hlsli"
#include "particle.hlsli"

bool noop_stack_clip(ConstantBuffer<CoarseConfig> settings, uint2 layer, CoarseDraw draw, ByteAddressBuffer paths,
    ByteAddressBuffer backdrops, ByteAddressBuffer ranges, ByteAddressBuffer paint, uint2 tile) {
    if (layer.x != LAYER_CLIP) return false;
    if (draw_has_sdf(draw)) return sdf_clip_covers(paint, draw, tile);
    uint backdrop = draw_backdrop(paths, draw, tile, uint2(settings.tiles_width, settings.tiles_height));
    if (backdrop == INVALID_INDEX) return false;
    uint2 range = ranges.Load2(backdrop * TILE_SEGMENT_RANGE_STRIDE);
    uint winding = backdrops.Load(backdrop * 4u);
    return range.x == range.y && (draw.fill_rule == FILL_EVEN_ODD ? (winding & 1u) != 0u : winding != 0u);
}
void emit_stack_begins(ConstantBuffer<CoarseConfig> settings, RWByteAddressBuffer work, ByteAddressBuffer layers,
    ByteAddressBuffer draws, ByteAddressBuffer paths, ByteAddressBuffer backdrops, ByteAddressBuffer ranges,
    ByteAddressBuffer paint, uint destination, uint2 tile) {
    for (uint index = settings.layer_stack_start; index < settings.layer_stack_end; index++) {
        uint3 layer = layers.Load3(index * LAYER_RECORD_STRIDE);
        if (layer.x > LAYER_BLEND) continue;
        CoarseDraw draw = load_draw(draws, layer.y);
        if (noop_stack_clip(settings, layer.xy, draw, paths, backdrops, ranges, paint, tile)) continue;
        if (layer.x == LAYER_CLIP && draw_has_sdf(draw)) {
            store_particle(work, settings, destination++, PTCL_BEGIN_SDF_CLIP, 0u, 0u, uint2(0u,0u), layer.y);
        } else {
            uint backdrop = draw_backdrop(paths, draw, tile, uint2(settings.tiles_width, settings.tiles_height));
            if (backdrop == INVALID_INDEX) continue;
            uint tag = layer.x == LAYER_OPACITY ? PTCL_BEGIN_OPACITY : (layer.x == LAYER_BLEND ? PTCL_BEGIN_BLEND : PTCL_BEGIN_CLIP);
            store_particle(work, settings, destination++, tag, backdrops.Load(backdrop * 4u), draw.fill_rule, ranges.Load2(backdrop * TILE_SEGMENT_RANGE_STRIDE), layer.z);
        }
    }
}
void emit_stack_ends(ConstantBuffer<CoarseConfig> settings, RWByteAddressBuffer work, ByteAddressBuffer layers,
    ByteAddressBuffer draws, ByteAddressBuffer paths, ByteAddressBuffer backdrops, ByteAddressBuffer ranges,
    ByteAddressBuffer paint, uint destination, uint2 tile) {
    for (uint index = settings.layer_stack_end; index > settings.layer_stack_start;) {
        uint3 layer = layers.Load3(--index * LAYER_RECORD_STRIDE);
        if (layer.x > LAYER_BLEND) continue;
        CoarseDraw draw = load_draw(draws, layer.y);
        if (noop_stack_clip(settings, layer.xy, draw, paths, backdrops, ranges, paint, tile)) continue;
        uint tag = layer.x == LAYER_OPACITY ? PTCL_END_OPACITY : (layer.x == LAYER_BLEND ? PTCL_END_BLEND : PTCL_END_CLIP);
        store_particle(work, settings, destination++, tag, 0u, 0u, uint2(0u,0u), 0u);
    }
}

#endif // TILEINK_HLSL_COARSE_EMIT_STACK_HLSLI_INCLUDED

sources.coarse/paint.hlsli:
#ifndef TILEINK_HLSL_COARSE_PAINT_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_PAINT_HLSLI_INCLUDED

#include "config.hlsli"
#include "draw.hlsli"
#include "sdf_clip.hlsli"
#include "particle.hlsli"

static const uint BRUSH_SOLID = 1u;
static const uint BRUSH_PATTERN_RESOURCE = 7u;
static const uint BRUSH_COLOR_OFFSET = 16u;
static const uint BRUSH_IMAGE_ALPHA_OFFSET = 28u;
static const uint SDF_CANDLESTICK = 5u;
static const uint SDF_CHECKERBOARD = 14u;

uint brush_base(ConstantBuffer<CoarseConfig> settings, CoarseDraw draw) { return (settings.paint_brush_base + draw.brush_offset) * 4u; }
bool nontransparent_solid(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw) {
    if (draw.brush_offset == INVALID_INDEX) return false;
    uint base = brush_base(settings, draw);
    return paint.Load(base) == BRUSH_SOLID && paint.Load(base + BRUSH_COLOR_OFFSET) != 0u;
}
uint solid_color(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw) {
    return paint.Load(brush_base(settings, draw) + BRUSH_COLOR_OFFSET);
}
bool solid_supported_sdf(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw) {
    if (!nontransparent_solid(paint, settings, draw) || draw.sdf_offset == INVALID_INDEX || draw.shadow_offset != INVALID_INDEX || draw.sdf_len == 0u) return false;
    uint kind = paint.Load(draw.sdf_offset * 4u);
    return kind == SDF_RECT || kind == SDF_CANDLESTICK || kind == SDF_CHECKERBOARD;
}
uint full_tile_solid(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw, uint2 tile) {
    return nontransparent_solid(paint, settings, draw) && sdf_clip_covers(paint, draw, tile) ? solid_color(paint, settings, draw) : 0u;
}
bool full_tile_image(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw, uint2 tile) {
    if (draw.brush_offset == INVALID_INDEX) return false;
    uint base = brush_base(settings, draw);
    return paint.Load(base) == BRUSH_PATTERN_RESOURCE && paint.Load(base + BRUSH_IMAGE_ALPHA_OFFSET) == 255u && sdf_clip_covers(paint, draw, tile);
}
uint particle_class_flags(ByteAddressBuffer paint, ConstantBuffer<CoarseConfig> settings, CoarseDraw draw, uint tag) {
    if (tag == PTCL_COLOR) return CHUNK_CLASS_COLOR;
    if (tag == PTCL_IMAGE || (tag == PTCL_SDF && solid_supported_sdf(paint, settings, draw))) return CHUNK_CLASS_SDF;
    return CHUNK_CLASS_OTHER;
}

#endif // TILEINK_HLSL_COARSE_PAINT_HLSLI_INCLUDED

sources.coarse/particle.hlsli:
#ifndef TILEINK_HLSL_COARSE_PARTICLE_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_PARTICLE_HLSLI_INCLUDED

#include "../coarse_records.hlsli"
#include "config.hlsli"
#include "tags.hlsli"

static const uint PTCL_END = 0u;
static const uint PTCL_FILL = 1u;
static const uint PTCL_COLOR = 2u;
static const uint PTCL_BEGIN_CLIP = 3u;
static const uint PTCL_END_CLIP = 4u;
static const uint PTCL_BEGIN_OPACITY = 5u;
static const uint PTCL_END_OPACITY = 6u;
static const uint PTCL_BEGIN_BLEND = 7u;
static const uint PTCL_END_BLEND = 8u;
static const uint PTCL_SDF = 9u;
static const uint PTCL_GLYPH = 10u;
static const uint PTCL_PATH_GLYPH = 11u;
static const uint PTCL_BEGIN_SDF_CLIP = 12u;
static const uint PTCL_IMAGE = 13u;

struct Particle {
    bool valid;
    uint glyph_count, tag, winding, fill_rule;
    uint2 segments;
    uint color;
};
Particle empty_particle() {
    Particle result;
    result.valid = false;
    result.glyph_count = 0u;
    result.tag = PTCL_FILL;
    result.winding = 0u;
    result.fill_rule = 0u;
    result.segments = uint2(0u,0u);
    result.color = 0u;
    return result;
}
void store_particle(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings,
    uint destination, uint tag, uint winding, uint fill_rule, uint2 segments, uint color) {
    if (destination >= settings.ptcl_capacity) return;
    uint base = settings.tile_count * COARSE_TILE_RECORD_STRIDE + destination * COARSE_PTCL_RECORD_STRIDE;
    work.Store4(base, uint4(tag, winding, fill_rule, segments.x));
    work.Store2(base + 16u, uint2(segments.y, color));
}
void store_particle_value(RWByteAddressBuffer work, ConstantBuffer<CoarseConfig> settings, uint destination, Particle value) {
    store_particle(work, settings, destination, value.tag, value.winding, value.fill_rule, value.segments, value.color);
}


#endif // TILEINK_HLSL_COARSE_PARTICLE_HLSLI_INCLUDED

sources.coarse/prefix_scan.hlsli:
#ifndef TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED

#include "../constants.hlsli"
// Particle and glyph allocation use the same ordered, wrapping-u32 scan.
// Workgroup scratch is private to this helper; both prefix and total are explicit outputs.
groupshared uint2 coarse_prefix_scratch[COARSE_WORKGROUP_SIZE];
groupshared uint2 coarse_prefix_total;

uint2 exclusive_prefix(uint2 value, uint lane, out uint2 total) {
    coarse_prefix_scratch[lane] = value;
    GroupMemoryBarrierWithGroupSync();
    for (uint upsweep_step = 1u; upsweep_step < COARSE_WORKGROUP_SIZE; upsweep_step *= 2u) {
        uint index = (lane + 1u) * upsweep_step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) coarse_prefix_scratch[index] += coarse_prefix_scratch[index - upsweep_step];
        GroupMemoryBarrierWithGroupSync();
    }
    if (lane == 0u) {
        coarse_prefix_total = coarse_prefix_scratch[COARSE_WORKGROUP_SIZE - 1u];
        coarse_prefix_scratch[COARSE_WORKGROUP_SIZE - 1u] = uint2(0u, 0u);
    }
    GroupMemoryBarrierWithGroupSync();
    for (uint downsweep_step = COARSE_WORKGROUP_SIZE / 2u; downsweep_step > 0u; downsweep_step /= 2u) {
        uint index = (lane + 1u) * downsweep_step * 2u - 1u;
        if (index < COARSE_WORKGROUP_SIZE) {
            uint left = index - downsweep_step;
            uint2 previous = coarse_prefix_scratch[left];
            coarse_prefix_scratch[left] = coarse_prefix_scratch[index];
            coarse_prefix_scratch[index] += previous;
        }
        GroupMemoryBarrierWithGroupSync();
    }
    uint2 result = coarse_prefix_scratch[lane];
    total = coarse_prefix_total;
    GroupMemoryBarrierWithGroupSync();
    return result;
}

#endif // TILEINK_HLSL_COARSE_PREFIX_SCAN_HLSLI_INCLUDED

sources.coarse/sdf_clip.hlsli:
#ifndef TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED
#define TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED

#include "draw.hlsli"

static const float FULL_TILE_SDF_INSET = 0.5;
bool rounded_corner_covers(float2 position, float2 corner, float2 center, float radius) {
    bool in_square = radius > 0.0 && all(abs(position - corner) < radius);
    float inner_radius = radius - FULL_TILE_SDF_INSET;
    float2 delta = position - center;
    return !in_square || (inner_radius > 0.0 && dot(delta, delta) <= inner_radius * inner_radius);
}
bool sdf_clip_covers(ByteAddressBuffer sdf, CoarseDraw draw, uint2 tile) {
    if (draw.sdf_offset == INVALID_INDEX || draw.shadow_offset != INVALID_INDEX || draw.sdf_len < 9u) return false;
    uint base = draw.sdf_offset * 4u;
    if (sdf.Load(base) != SDF_RECT || any(draw.affine_linear != float4(1.0, 0.0, 0.0, 1.0))) return false;
    float4 rect = asfloat(sdf.Load4(base + 4u));
    float2 lower = min(rect.xy, rect.zw);
    float2 upper = max(rect.xy, rect.zw);
    float2 tile_lower = float2(tile * TILE_SIZE) + 0.5 - draw.translation;
    float2 tile_upper = tile_lower + float(TILE_SIZE - 1u);
    float2 size = upper - lower;
    if (any(size < float(TILE_SIZE - 1u) + 2.0 * FULL_TILE_SDF_INSET) || any(tile_lower < lower + FULL_TILE_SDF_INSET) || any(tile_upper > upper - FULL_TILE_SDF_INSET)) return false;
    float limit = min(size.x, size.y) * 0.5;
    float4 radii = min(max(asfloat(sdf.Load4(base + 20u)), 0.0), limit);
    return rounded_corner_covers(tile_lower, lower, lower + radii.x, radii.x)
        && rounded_corner_covers(float2(tile_upper.x, tile_lower.y), float2(upper.x, lower.y), float2(upper.x-radii.y, lower.y+radii.y), radii.y)
        && rounded_corner_covers(float2(tile_lower.x, tile_upper.y), float2(lower.x, upper.y), float2(lower.x+radii.z, upper.y-radii.z), radii.z)
        && rounded_corner_covers(tile_upper, upper, upper-radii.w, radii.w);
}

#endif // TILEINK_HLSL_COARSE_SDF_CLIP_HLSLI_INCLUDED

